// ── SÉCURITÉ : Anti-Prompt Injection + Limite taille ──────────────────────
function sanitizeInput(text) {
  if (!text || typeof text !== 'string') return text;

  // Limite taille : 50 000 chars max (environ 12 500 tokens)
  if (text.length > 50000) {
    text = text.substring(0, 50000) + '\n[TRONQUÉ — limite 50K chars atteinte]';
  }

  // Anti-prompt injection : neutraliser les tentatives d'override
  const injectionPatterns = [
    /ignore\s+(all\s+)?previous\s+instructions?/gi,
    /ignore\s+(toutes?\s+)?les?\s+instructions?\s+précédentes?/gi,
    /you\s+are\s+now\s+a/gi,
    /tu\s+es\s+maintenant/gi,
    /\[SYSTEM\]/gi,
    /\[INST\]/gi,
    /<\|system\|>/gi,
    /\[\[reset\]\]/gi,
  ];

  for (const pattern of injectionPatterns) {
    text = text.replace(pattern, '[FILTRÉ]');
  }

  return text;
}

var items = $input.all();

if (!items || items.length === 0) {
  return [{
    json: {
      valid: false,
      error: "Aucune donnée reçue du webhook",
      specs: null
    }
  }];
}

var inputJson = items[0].json;

// Extraire le body selon la structure reçue
var data = inputJson;

// Cas 1 : webhook retourne {headers, params, query, body, ...}
if (inputJson.body !== undefined) {
  var rawBody = inputJson.body;
  if (typeof rawBody === 'string') {
    // Supprimer le = parasite en préfixe si présent
    rawBody = rawBody.replace(/^=+/, '').trim();
    try {
      data = JSON.parse(rawBody);
    } catch(e) {
      data = inputJson;
    }
  } else if (typeof rawBody === 'object') {
    data = rawBody;
  }
}

// Cas 2 : les champs sont directement dans l'objet racine
var task_id     = data.task_id     || inputJson.task_id     || null;
var userRequest = sanitizeInput(data.userRequest || inputJson.userRequest || null);
var language    = data.language    || inputJson.language    || 'javascript';
var framework   = data.framework   || inputJson.framework   || 'express';
var architecture = data.architecture || inputJson.architecture || {};

if (!userRequest || userRequest.trim() === '') {
  return [{
    json: {
      valid: false,
      error: "Le champ 'userRequest' est manquant ou vide. Clés reçues: " + Object.keys(data).join(', '),
      specs: null,
      debug: {
        received_keys: Object.keys(inputJson).join(', '),
        data_keys: Object.keys(data).join(', '),
        input_preview: JSON.stringify(inputJson).substring(0, 500)
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    error: null,
    specs: userRequest.trim(),
    userRequest: userRequest.trim(),
    task_id: task_id,
    language: language,
    environment: (typeof data.environment === 'string' ? data.environment : 'staging'),
    framework: framework,
    architecture: architecture,
    debug: {
      received_keys: Object.keys(data).join(', ')
    }
  }
}];

let task_id = "unknown";
try { task_id = $('Validate Specs').first().json.task_id || "unknown"; } catch(e) {}

const injectData = $('Inject Prompt').first().json;
const mode = injectData.mode || 'deterministic';
let serverJs = injectData._server_js || injectData.base_server_js || '';

// Garde-fou SÉCURITÉ (thèse : LLM = compréhension, déterministe = code sûr).
// En mode amélioration, le LLM réécrit server.js : on n'accepte SA version que
// si elle ne contient AUCUN motif SAST-critique (mêmes règles que l'Agent SAST).
// Sinon → repli sur la version DÉTERMINISTE (base_server_js), qui implémente
// déjà l'amélioration de façon sûre. Empêche le LLM d'introduire une faille.
function _llmSastCritical(code) {
  code = String(code || '');
  var hasUserInput = /req\.(body|params|query)/.test(code);
  if (/fetch\s*\(\s*req\.(body|params|query)/i.test(code) || /axios\.\w+\s*\(\s*req\.(body|params|query)/i.test(code) || /url\s*[:=]\s*req\.(body|params|query)/i.test(code)) return 'SSRF-001';
  if (/__proto__\s*=/.test(code) || /\[['"]__proto__['"]\]\s*=/.test(code) || /Object\.assign\s*\(\s*\{\}\s*,\s*req\.(body|params|query)/i.test(code)) return 'PROTO-001';
  if (/(?:readFile|writeFile|createReadStream|unlink)[A-Za-z]*\s*\([^)]*req\.(?:body|params|query)/.test(code)) return 'PATH-001';
  if (/node-serialize/.test(code) || /unserialize\s*\(/.test(code) || /yaml\.load\s*\(/.test(code)) return 'DESER-001';
  if (/res\.redirect\s*\(/.test(code) && hasUserInput) return 'REDIR-001';
  if (/createHash\s*\(\s*['"`]md5['"`]/i.test(code) || /createHash\s*\(\s*['"`]sha1['"`]/i.test(code) || /createCipher\s*\(\s*['"`]des/i.test(code)) return 'CRYPTO-001';
  if (/Math\.random\s*\(\)/.test(code) && /(token|secret|session|password|key|auth|csrf|nonce)/i.test(code)) return 'RAND-001';
  if (/execSync\s*\(/.test(code) && hasUserInput) return 'CMD-001';
  if (/`[^`]*\b(?:SELECT|INSERT|UPDATE|DELETE|WHERE|FROM)\b[^`]*\$\{[^}]*\breq\.(?:query|body|params)\b/i.test(code)) return 'SQLI-001';
  if (/['"][^'"]*\b(?:SELECT|INSERT|UPDATE|DELETE|WHERE|FROM)\b[^'"]*['"]\s*\+[^;\n]*\breq\.(?:query|body|params)\b/i.test(code)) return 'SQLI-001';
  if (/\beval\s*\(/.test(code) || /new\s+Function\s*\(/.test(code)) return 'EVAL-001';
  if (/res\.(send|write|end)\s*\([^)]*req\.(body|params|query)/i.test(code)) return 'XSS-001';
  return null;
}

if (mode === 'llm_improve') {
  // Parser la réponse LLM
  try {
    let data;
    if ($json.choices?.[0]?.message?.content) {
      const content = $json.choices[0].message.content;
      data = typeof content === "string" ? JSON.parse(content) : content;
    }
    if (data?.server_js && typeof data.server_js === 'string' && data.server_js.length > 100) {
      // Valider que les routes sont préservées
      const routes = injectData.endpoints || [];
      let allPresent = true;
      routes.forEach(ep => {
        if (ep.path !== '/health') {
          const method = ep.method.toLowerCase();
          if (!data.server_js.includes("app." + method + "('" + ep.path + "'")) {
            allPresent = false;
            console.log("Route manquante dans LLM output: " + ep.method + " " + ep.path);
          }
        }
      });
      var _sastRule = _llmSastCritical(data.server_js);
      if (!allPresent) {
        console.log("⚠️ Routes manquantes — fallback déterministe");
      } else if (_sastRule) {
        console.log("⛔ LLM improve rejeté (motif SAST-critique " + _sastRule + ") — repli déterministe sûr");
      } else {
        serverJs = data.server_js;
        console.log("✅ LLM amélioration appliquée (SAST-clean)");
      }
    }
  } catch(e) {
    console.log("Erreur parse LLM improve:", e.message, "— fallback déterministe");
  }
}

// Lire package.json depuis Inject Prompt (inclut better-sqlite3 en V5.8)
const packageJson = injectData._package_json || JSON.stringify({
  name: 'api', version: '1.0.0', main: 'server.js',
  scripts: { start: 'node server.js' },
  dependencies: { express: '^4.18.2', dotenv: '^16.0.0', 'better-sqlite3': '^9.4.3' }
}, null, 2);

// Récupérer stores et data_model depuis Inject Prompt pour les propager
const _inj = injectData; // déjà lu : $('Inject Prompt').first().json
const _stores    = _inj.stores    || {};
const _dataModel = _inj.data_model || {};
const _endpoints = _inj.priority_endpoints || _inj.endpoints || [];

// Fichiers SQLite additionnels
const _dbJs      = injectData._db_js      || '';
const _schemaSql = injectData._schema_sql || '';

// environment (staging|production) propage depuis l UI -> NODE_ENV de l app generee
var _NODE_ENV = 'development';
try { _NODE_ENV = ($('Validate Specs').first().json.environment === 'production') ? 'production' : 'development'; } catch(e) {}

const _files = [
  { path: 'server.js',    content: '// FILE: server.js\n' + serverJs },
  { path: 'package.json', content: '// FILE: package.json\n' + packageJson },
  { path: '.env.example', content: '// FILE: .env.example\nPORT=3000\nDB_PATH=./database.db\nNODE_ENV=' + _NODE_ENV + '\n# JWT_SECRET optionnel : genere automatiquement au 1er lancement si absent.\n# Le definir manuellement pour partager la session entre plusieurs instances.\nJWT_SECRET=\n' }
];
if (_dbJs.length > 10)      _files.push({ path: 'db.js',      content: '// FILE: db.js\n'      + _dbJs });
if (_schemaSql.length > 10) _files.push({ path: 'schema.sql', content: '-- FILE: schema.sql\n' + _schemaSql });
const _testsSec = injectData._tests_security_js || '';
if (_testsSec.length > 20) _files.push({ path: 'tests/security.test.js', content: _testsSec });


// -- SECURITY.md : attestation OWASP Top 10 2021 + ASVS 4.0, basee sur analyse du code genere --
(function(){
  var sj = serverJs || '';
  function has(re){ return re.test(sj); }
  var ctrl = {
    csp: has(/contentSecurityPolicy:\s*\{/) && !has(/contentSecurityPolicy:\s*false/),
    helmet: has(/helmet\(/),
    auth: has(/authMiddleware/),
    bcrypt: has(/bcrypt/),
    jwt: has(/jwt\.sign|jsonwebtoken/),
    cookieHttpOnly: has(/httpOnly:\s*true/),
    cookieSameSite: has(/sameSite/),
    rateLimit: has(/rateLimit\(/),
    validation: has(/validationResult|express-validator|handleValidation/),
    paramSql: has(/\.prepare\(/),
    isolation: has(/user_id/) && has(/WHERE[\s\S]{0,60}user_id/i),
    secret: has(/JWT_SECRET/) && has(/randomBytes/),
    // -- Tier 2 : durcissement authentification / session --
    lockout: has(/locked_until/) && has(/LOCK_MAX_FAILS|failed_attempts/),
    revocation: has(/token_version/),
    changePw: has(/change-password/),
    audit: has(/_audit\s*\(/),
    // -- Fonctionnalites complementaires --
    rbac: has(/req\.user\.role|user\.role\b|authorize\s*\(/),
    sharing: has(/created_by/),
    uploads: has(/multer|\/uploads\b/),
    csrfSameSite: has(/sameSite:\s*['"]strict['"]/i)
  };
  // Le deploiement clef-en-main (Dockerfile multi-stage + compose + nginx) est
  // toujours emis par le pipeline -> atteste inconditionnellement, decrit precisement.
  var hasDeploy = true;
  function mk(ok){ return ok ? 'OK' : 'A verifier'; }
  function mkNA(ok){ return ok ? 'OK' : 'N/A'; }
  var resources = [];
  try { resources = Object.keys(_stores || {}); } catch(e){}
  var L = [];
  L.push('# Rapport de securite');
  L.push('');
  L.push('Genere automatiquement par Forge IA. Atteste des controles de securite integres a l application, mappes sur OWASP Top 10 2021 et OWASP ASVS 4.0. Base sur une analyse statique du code genere (server.js) et des artefacts du pipeline.');
  L.push('');
  L.push('## Synthese OWASP Top 10 2021');
  L.push('');
  L.push('| Categorie | Controle integre | Statut |');
  L.push('|---|---|---|');
  L.push('| A01 Broken Access Control | Isolation par utilisateur (user_id + WHERE) et authMiddleware sur les routes' + (ctrl.rbac ? ' ; controle de role (RBAC) sur les actions sensibles' : '') + ' | ' + mk(ctrl.auth && ctrl.isolation) + ' |');
  L.push('| A02 Cryptographic Failures | Mots de passe haches bcrypt (12 rounds), JWT signe, cookies Secure en production, secret genere aleatoirement | ' + mk(ctrl.bcrypt && ctrl.jwt && ctrl.secret) + ' |');
  L.push('| A03 Injection | Requetes SQL parametrees (prepare + placeholders), validation des entrees (express-validator), CSP stricte | ' + mk(ctrl.paramSql && ctrl.validation && ctrl.csp) + ' |');
  L.push('| A04 Insecure Design | Rate-limiting, verrouillage de compte apres echecs, moindre privilege (donnees cloisonnees par compte) | ' + mk(ctrl.rateLimit && ctrl.isolation && ctrl.lockout) + ' |');
  L.push('| A05 Security Misconfiguration | helmet : CSP stricte a nonce, HSTS, nosniff, anti-clickjacking | ' + mk(ctrl.helmet && ctrl.csp) + ' |');
  L.push('| A06 Vulnerable and Outdated Components | Dependances epinglees dans package.json + SBOM CycloneDX (bom.json) ; voir rapport SCA / npm audit | Voir SCA |');
  L.push('| A07 Identification and Authentication Failures | bcrypt, rate-limit login, verrouillage temporaire du compte, expiration JWT, cookie HttpOnly + SameSite, revocation de session | ' + mk(ctrl.bcrypt && ctrl.rateLimit && ctrl.cookieHttpOnly && ctrl.cookieSameSite && ctrl.lockout && ctrl.revocation) + ' |');
  L.push('| A08 Software and Data Integrity Failures | Secret JWT genere aleatoirement (jamais en dur), version de jeton (token_version) verifiee a chaque requete | ' + mk(ctrl.secret && ctrl.revocation) + ' |');
  L.push('| A09 Security Logging and Monitoring Failures | ' + (ctrl.audit ? 'Journal d audit des evenements sensibles (connexion, echec, verrouillage, changement de mot de passe) + journalisation des erreurs par route' : 'Journalisation des erreurs serveur par route') + ' | ' + (ctrl.audit ? 'OK' : 'Basique') + ' |');
  L.push('| A10 SSRF | Aucune requete sortante pilotee par une entree utilisateur | OK |');
  L.push('');
  L.push('## Durcissement Tier 2 (authentification & session)');
  L.push('');
  L.push('- **Verrouillage de compte** : apres plusieurs echecs consecutifs, le compte est verrouille temporairement (colonnes `failed_attempts` / `locked_until`), reponse HTTP 429. ' + mkNA(ctrl.lockout));
  L.push('- **Revocation de session** : chaque jeton porte une version (`token_version`) verifiee a chaque requete ; la deconnexion et le changement de mot de passe l incrementent, invalidant les anciens jetons. ' + mkNA(ctrl.revocation));
  L.push('- **Changement de mot de passe authentifie** : endpoint `POST /api/change-password` (verification du mot de passe actuel, re-hachage bcrypt, revocation des autres sessions). ' + mkNA(ctrl.changePw));
  L.push('- **Journal d audit** : evenements d authentification et de mutation traces avec acteur, ressource et IP reelle. ' + mkNA(ctrl.audit));
  L.push('');
  L.push('## Controles ASVS 4.0 (extraits)');
  L.push('');
  L.push('- V2 Authentication : hachage bcrypt (12 rounds), longueur minimale de mot de passe, limitation des tentatives + verrouillage temporaire. ' + mk(ctrl.bcrypt && ctrl.rateLimit && ctrl.lockout));
  L.push('- V3 Session Management : JWT en cookie HttpOnly + SameSite=strict, expiration 8h, revocation serveur via token_version (logout + changement de mot de passe). ' + mk(ctrl.cookieHttpOnly && ctrl.jwt && ctrl.revocation));
  L.push('- V4 Access Control : verification du proprietaire (user_id) sur chaque acces ressource' + (ctrl.rbac ? ', controle de role sur les actions privilegiees' : '') + '. ' + mk(ctrl.isolation));
  L.push('- V5 Validation, Sanitization and Encoding : validation des entrees, requetes parametrees, echappement HTML cote client. ' + mk(ctrl.validation && ctrl.paramSql));
  L.push('- V7 Error Handling and Logging : messages d erreur generiques cote client, ' + (ctrl.audit ? 'journal d audit des evenements de securite' : 'journalisation des erreurs') + '. ' + mk(true));
  L.push('- V14 Configuration : en-tetes de securite via helmet, CSP stricte, pas de secret en dur. ' + mk(ctrl.helmet && ctrl.secret));
  if (ctrl.uploads) L.push('- V12 File and Resources : televersements traites par multer avec limites de type et de taille, stockage hors racine web. OK');
  L.push('');
  L.push('## Ressources protegees');
  L.push('');
  if (resources.length) { resources.forEach(function(r){ L.push('- ' + r + ' : cloisonnee par user_id' + (ctrl.sharing ? ' (partage controle par le proprietaire via `created_by`)' : '')); }); }
  else { L.push('- (aucune ressource metier detectee)'); }
  L.push('');
  if (hasDeploy) {
    L.push('## Deploiement securise (artefacts fournis)');
    L.push('');
    L.push('- **Image multi-stage** (`Dockerfile`) : l etape de build compile better-sqlite3, l image finale n embarque que le runtime (aucun compilateur ni outil de build).');
    L.push('- **Conteneur non-root** : l application s execute sous l utilisateur `node` (uid 1000), jamais `root` (moindre privilege, OWASP A04). Verifie par analyse Semgrep du Dockerfile.');
    L.push('- **Isolation des donnees** (`docker-compose.yml`) : base SQLite dans un volume dedie `/data`, redemarrage automatique, secret injectable par variable d environnement.');
    L.push('- **Reverse proxy** (`deploy/nginx.conf`) : `client_max_body_size` calibre pour les uploads (evite le 413), en-tetes `X-Forwarded-*` pour journaliser l IP reelle, reglages SSE pour le temps reel.');
    L.push('- **Secret de session** : `JWT_SECRET` genere aleatoirement au 1er lancement, persiste hors du code ; a fixer via l environnement pour un deploiement multi-instances.');
    L.push('- Procedure detaillee dans `DEPLOY.md`.');
    L.push('');
  }
  L.push('## Limites connues');
  L.push('');
  L.push('- Inscription ouverte (/api/register public) : choix MVP ; le cloisonnement par compte limite le risque.');
  L.push('- Journal d audit applicatif (pas de SIEM ni alerting externe).');
  L.push('- Se referer aux rapports DAST et SCA du pipeline pour les tests dynamiques et la chaine d approvisionnement.');
  _files.push({ path: 'SECURITY.md', content: L.join('\n') });
})();



// -- bom.json : SBOM CycloneDX 1.5 (deterministe depuis package.json) - OWASP A06 chaine d appro --
(function(){
  try {
    var _pf = _files.find(function(f){ return f.path === 'package.json'; });
    if (!_pf) return;
    var _pj = JSON.parse(String(_pf.content || '').replace(/^\/\/ FILE:.*\n/, '').trim());
    var _deps = {};
    Object.assign(_deps, _pj.dependencies || {}, _pj.devDependencies || {});
    var _components = Object.keys(_deps).map(function(name){
      var ver = String(_deps[name]).replace(/[^0-9.]/g, '');
      var purl = 'pkg:npm/' + name + '@' + ver;
      return { type: 'library', 'bom-ref': purl, name: name, version: ver, purl: purl };
    });
    var _bom = {
      bomFormat: 'CycloneDX',
      specVersion: '1.5',
      version: 1,
      metadata: {
        timestamp: new Date().toISOString(),
        tools: [{ vendor: 'Forge IA', name: 'SBOM Generator', version: '1.0' }],
        component: { type: 'application', name: _pj.name || 'generated-app', version: _pj.version || '1.0.0' }
      },
      components: _components
    };
    _files.push({ path: 'bom.json', content: JSON.stringify(_bom, null, 2) });
  } catch(e) {}
})();


// -- Axe 3 : artefacts de deploiement clef-en-main (Dockerfile + compose + nginx + DEPLOY.md) --
(function(){
  try {
    var _appName = 'app';
    try { var _pf = _files.find(function(f){ return f.path === 'package.json'; }); if (_pf) { var _pj = JSON.parse(String(_pf.content || '').replace(/^\/\/ FILE:.*\n/, '').trim()); if (_pj.name) _appName = String(_pj.name); } } catch(e){}
    var _svc = _appName.replace(/[^a-zA-Z0-9_-]/g, '-').toLowerCase() || 'app';

    // Dockerfile multi-stage : la 1re etape compile better-sqlite3 (natif), la 2e
    // n'embarque que le runtime -> image finale sans outils de build.
    _files.push({ path: 'Dockerfile', content:
'# Image de production — genere par Forge IA\n' +
'FROM node:20-slim AS build\n' +
'WORKDIR /app\n' +
'RUN apt-get update && apt-get install -y --no-install-recommends python3 make g++ && rm -rf /var/lib/apt/lists/*\n' +
'COPY package.json package-lock.json* ./\n' +
'RUN npm install --omit=dev\n' +
'\n' +
'FROM node:20-slim\n' +
'WORKDIR /app\n' +
'COPY --from=build /app/node_modules ./node_modules\n' +
'COPY . .\n' +
'ENV NODE_ENV=production\n' +
'ENV PORT=3000\n' +
'ENV DB_PATH=/data/database.db\n' +
'# Securite (moindre privilege) : ne pas tourner en root. L image node fournit\n' +
'# un utilisateur non-root "node" (uid 1000). On lui donne /app (secret .jwt_secret)\n' +
'# et /data (base SQLite, monte en volume) puis on abaisse les privileges.\n' +
'RUN mkdir -p /data && chown -R node:node /data /app\n' +
'USER node\n' +
'EXPOSE 3000\n' +
'CMD ["node", "server.js"]\n' });

    _files.push({ path: '.dockerignore', content:
'node_modules\nnpm-debug.log\n*.db\n*.db-wal\n*.db-shm\n.env\n.git\nDockerfile\ndocker-compose.yml\n' });

    // docker-compose : persiste la base dans un volume (DB_PATH=/data), redemarre seul.
    _files.push({ path: 'docker-compose.yml', content:
'services:\n' +
'  ' + _svc + ':\n' +
'    build: .\n' +
'    container_name: ' + _svc + '\n' +
'    restart: unless-stopped\n' +
'    ports:\n' +
'      - "3000:3000"   # hote:conteneur — adaptez le port hote si besoin\n' +
'    environment:\n' +
'      - NODE_ENV=production\n' +
'      - PORT=3000\n' +
'      - DB_PATH=/data/database.db\n' +
'      # - JWT_SECRET=   # optionnel : definissez-le pour partager la session entre plusieurs instances\n' +
'    volumes:\n' +
'      - ' + _svc + '_data:/data   # persiste la base SQLite\n' +
'\n' +
'volumes:\n' +
'  ' + _svc + '_data:\n' });

    // Snippet nginx : reverse proxy + client_max_body_size (autorise les uploads,
    // regle le 413) + en-tetes X-Forwarded (l app journalise l IP reelle a l audit).
    _files.push({ path: 'deploy/nginx.conf', content:
'# Reverse proxy nginx pour ' + _appName + ' — genere par Forge IA\n' +
'# A adapter (server_name) puis inclure dans votre configuration nginx.\n' +
'server {\n' +
'    listen 80;\n' +
'    server_name votre-domaine.example;   # <-- a personnaliser\n' +
'\n' +
'    # Autorise les televersements (5 Mo apres decodage + marge) -> evite le 413\n' +
'    client_max_body_size 8m;\n' +
'\n' +
'    location / {\n' +
'        proxy_pass http://127.0.0.1:3000;   # port publie par docker-compose\n' +
'        proxy_http_version 1.1;\n' +
'        proxy_set_header Host $host;\n' +
'        proxy_set_header X-Real-IP $remote_addr;\n' +
'        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\n' +
'        proxy_set_header X-Forwarded-Proto $scheme;\n' +
'        # Temps reel (SSE /api/events) : pas de mise en tampon, connexion longue\n' +
'        proxy_set_header Connection "";\n' +
'        proxy_buffering off;\n' +
'        proxy_read_timeout 3600s;\n' +
'    }\n' +
'}\n' });

    _files.push({ path: 'DEPLOY.md', content:
'# Deploiement — ' + _appName + '\n\n' +
'Application Node.js / Express / SQLite generee par Forge IA, prete a lancer.\n\n' +
'## Option A — Docker (recommande)\n\n' +
'```bash\n' +
'docker compose up -d --build\n' +
'```\n\n' +
'- L app ecoute sur le port **3000** du conteneur, publie sur **3000** de l hote (modifiable dans `docker-compose.yml`).\n' +
