  var lines = ['CREATE TABLE IF NOT EXISTS ' + sn + ' ('];
  var colDefs = [];
  colDefs.push('  id INTEGER PRIMARY KEY AUTOINCREMENT');
  Object.keys(cfg.fields).filter(function(k){ return k !== 'id' && k !== 'created_at'; }).forEach(function(k) {
    var sType = sqlType(k, cfg.fields[k]);
    // Booleen : INTEGER 0/1, toujours defini (defaut 0 si absent) -> pas de NOT NULL bloquant
    var _bc = classifyField(k, cfg.fields[k]);
    if (_bc.kind === 'boolean') { var _bd = (_bc.def === true || _bc.def === 1 || String(_bc.def) === '1' || String(_bc.def).toLowerCase() === 'true') ? 1 : 0; colDefs.push('  ' + k + ' INTEGER NOT NULL DEFAULT ' + _bd); return; }
    var notNull = cfg.requiredFields.includes(k) ? ' NOT NULL' : '';
    // FK reference
    var fkRef = '';
    if (k.endsWith('_id') && sType === 'INTEGER') {
      var refBase = k.replace(/_id$/, '');
      var refTable = refBase + 's';
      if (storeNames.includes(refTable)) fkRef = ' REFERENCES ' + refTable + '(id)';
      else if (storeNames.includes(refBase)) fkRef = ' REFERENCES ' + refBase + '(id)';
    }
    // #3 : DEFAULT + contrainte CHECK (bornes) issus du modèle enrichi (secure by construction)
    var _m = classifyField(k, cfg.fields[k]);
    var _extra = '';
    if (_m.def != null && _m.def !== '' && !fkRef) {
      var _dv = (_m.kind === 'number') ? Number(_m.def) : "'" + String(_m.def).replace(/'/g, "''") + "'";
      if (!(_m.kind === 'number' && isNaN(_dv))) _extra += ' DEFAULT ' + _dv;
    }
    if (_m.kind === 'number' && (_m.min != null || _m.max != null)) {
      var _chk = [];
      if (_m.min != null && !isNaN(Number(_m.min))) _chk.push(k + ' >= ' + Number(_m.min));
      if (_m.max != null && !isNaN(Number(_m.max))) _chk.push(k + ' <= ' + Number(_m.max));
      if (_chk.length) _extra += ' CHECK(' + _chk.join(' AND ') + ')';
    }
    colDefs.push('  ' + k + ' ' + sType + notNull + fkRef + _extra);
  });
  colDefs.push('  ' + (cfg.shared ? 'created_by' : 'user_id') + ' INTEGER NOT NULL REFERENCES users(id)');
  colDefs.push("  created_at TEXT DEFAULT (datetime('now'))");
  lines.push(colDefs.join(',\n'));
  lines.push(');');
  return lines.join('\n');
}

