    language: "javascript",
    critical_issues: hasErrors
      ? errors.map(e => ({ severity: "high", description: String(e) }))
      : [],
    warnings: [],
    recommendations: hasFiles
      ? ["Code backend généré avec succès"]
      : ["Régénérer — aucun fichier produit"],
    summary: hasFiles
      ? `${files.length} fichier(s) backend généré(s)`
      : "Échec de génération backend",
    dimensions: {
      security: { score: 100 },
      quality: { score: hasFiles ? 100 : 0 }
    },
    timestamp: new Date().toISOString(),
    files,
    artifacts: input.artifacts || input.data?.specs?.artifacts || {},
    // Passer stores et data_model pour Build Frontend Payload
    stores:             _stores,
    data_model:         _dataModel,
    priority_endpoints: _endpoints
  }
}];

// Security Remediation (L0) — auto-vérification + corrections additives sûres (≤3 passes)
// Porte la "boucle de remédiation" DANS le Backend : après génération, on vérifie le code
// contre l'esprit des règles SAST déterministes et on applique UNIQUEMENT des correctifs
// additifs sûrs (durcissement manquant). On ne réécrit jamais la logique métier.
// Jamais bloquant : tout est encapsulé dans un try/catch qui renvoie l'entrée inchangée.
const input = $input.first().json;
const MAX_PASSES = 3;
try {
  const files = Array.isArray(input.files) ? input.files.map(function (f) { return Object.assign({}, f); }) : [];
  const idx = files.findIndex(function (f) {
    return f && f.path && f.path.replace(/\\/g, '/').split('/').pop() === 'server.js';
  });
  const report = { passes: 0, checks: [], fixes_applied: [], unresolved: [], converged: true };

  if (idx < 0) {
    return [{ json: Object.assign({}, input, { remediation: Object.assign({}, report, { note: 'server.js introuvable — vérification ignorée' }) }) }];
  }

  let code = String(files[idx].content || '');

  function detect(c) {
    const f = [];
    if (!/require\(['"]helmet['"]\)/.test(c) || !/app\.use\(\s*helmet/.test(c)) f.push('HDR-001:helmet');
    if (!/express-rate-limit/.test(c)) f.push('DOS-001:rate-limit');
    if (/app\.listen\(\s*\d+/.test(c) && !/process\.env\.PORT/.test(c)) f.push('CFG-001:port-env');
    if (!/['"]\/health['"]/.test(c)) f.push('OBS-001:health');
    if (/\beval\s*\(/.test(c)) f.push('EVAL-001:eval');
    if (/createHash\(\s*['"]md5['"]\s*\)/.test(c)) f.push('CRYPTO-001:md5');
    return f;
  }
  function insertAfterAppInit(c, line) {
    const m = c.match(/(^|\n)([^\n]*=\s*express\(\)\s*;?)/);
    if (!m) return null;
    const at = m.index + m[0].length;
    return c.slice(0, at) + '\n' + line + c.slice(at);
  }
  function insertBeforeListen(c, line) {
    const m = c.match(/\n[^\n]*app\.listen\s*\(/);
    if (!m) return c + '\n' + line + '\n';
    return c.slice(0, m.index) + '\n' + line + c.slice(m.index);
  }
  function ensureRequire(c, varName, mod) {
    if (new RegExp("require\\(['\"]" + mod + "['\"]\\)").test(c)) return c;
    return "const " + varName + " = require('" + mod + "');\n" + c;
  }

  const initialFindings = detect(code).slice();
  let pass = 0;
  while (pass < MAX_PASSES) {
    const cur = detect(code);
    let changed = false;

    if (cur.indexOf('HDR-001:helmet') >= 0) {
      const had = /require\(['"]helmet['"]\)/.test(code);
      code = ensureRequire(code, 'helmet', 'helmet');
      if (!had) { report.fixes_applied.push('HDR-001: require(helmet) ajouté'); changed = true; }
      if (!/app\.use\(\s*helmet/.test(code)) {
        const nc = insertAfterAppInit(code, "app.use(helmet());");
        if (nc) { code = nc; report.fixes_applied.push('HDR-001: app.use(helmet()) ajouté'); changed = true; }
        else report.unresolved.push("HDR-001: point d'insertion introuvable");
      }
    }
    if (cur.indexOf('DOS-001:rate-limit') >= 0) {
      code = ensureRequire(code, 'rateLimit', 'express-rate-limit');
      const nc = insertAfterAppInit(code, "app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100 }));");
      if (nc) { code = nc; report.fixes_applied.push('DOS-001: rate-limit ajouté'); changed = true; }
      else report.unresolved.push("DOS-001: point d'insertion introuvable");
    }
    if (cur.indexOf('CFG-001:port-env') >= 0) {
      const nc = code.replace(/app\.listen\(\s*(\d+)/, 'app.listen(process.env.PORT || $1');
      if (nc !== code) { code = nc; report.fixes_applied.push('CFG-001: PORT rendu dynamique'); changed = true; }
      else report.unresolved.push('CFG-001: app.listen non trouvé');
    }
    if (cur.indexOf('OBS-001:health') >= 0) {
      code = insertBeforeListen(code, "app.get('/health', (req, res) => res.json({ status: 'ok' }));");
      report.fixes_applied.push('OBS-001: endpoint /health ajouté'); changed = true;
    }
    if (cur.indexOf('EVAL-001:eval') >= 0) report.unresolved.push('EVAL-001: eval() présent (correction manuelle requise)');
    if (cur.indexOf('CRYPTO-001:md5') >= 0) report.unresolved.push('CRYPTO-001: md5 présent (correction manuelle requise)');

    pass++;
    if (!changed) break;
  }

  const after = detect(code);
  files[idx] = Object.assign({}, files[idx], { content: code });
  report.passes = pass;
  report.checks = ['HDR-001', 'DOS-001', 'CFG-001', 'OBS-001', 'EVAL-001', 'CRYPTO-001'];
  report.findings_before = initialFindings;
  report.findings_after = after;
  report.converged = after.filter(function (x) { return x.indexOf('EVAL') !== 0 && x.indexOf('CRYPTO') !== 0; }).length === 0;

  return [{ json: Object.assign({}, input, { files: files, remediation: report }) }];
} catch (e) {
  return [{ json: Object.assign({}, input, { remediation: { error: String((e && e.message) || e), passes: 0, fixes_applied: [], converged: true } }) }];
}
